const table = new Map();                       // rule base: key -> handler
const deadLetter = (msg) => dlq.publish(msg);

function publish(rules) {                      // control channel
  const next = new Map(rules);
  table.clear();
  for (const [k, v] of next) table.set(k, v);
}
export async function route(msg) {
  const handler = table.get(msg.key);          // one lookup per message
  await (handler ?? deadLetter)(msg);          // explicit fallback
}
